package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen3Test {







    @Test
    public void testRandom_WithCharsArrayAndStartEndZero() {
        char[] chars = {'a', 'b', 'c'};
        // When chars != null and start=0, end=0, end becomes chars.length (3)
        String result = RandomStringUtils.random(3, 0, 0, false, false, chars, new Random());
        assertEquals(3, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'a' || c == 'b' || c == 'c');
        }
    }












}

