public class RandomStringUtils_random_TriageGen3Test {













    @Test
    public void testRandom_SpecificRange() {
        // Test using specific start and end to avoid the 0,0 logic
        String result = RandomStringUtils.random(5, 'a', 'c' + 1, false, false, null, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c >= 'a' && c <= 'c');
        }
    }






