package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen3Test {

















    @Test
    public void testRandom_SurrogateLogic() {
        // We need to force the code into the surrogate branches.
        // High surrogate range: 55296 - 56191
        // Low surrogate range: 56320 - 57343
        // Private high surrogate: 56192 - 56319

        // We use a custom Random to return specific values to hit branches
        Random mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                // 1. Return index for High Surrogate (55296)
                // 2. Return index for Low Surrogate (56320)
                // 3. Return index for Private High Surrogate (56200)
                if (callCount == 1) return 0; // Index 0 -> 55296
                if (callCount == 2) return 1; // Index 1 -> 56320
                if (callCount == 3) return 2; // Index 2 -> 56200
                return 0;
            }
        };

        char[] surrogates = { (char)55296, (char)56320, (char)56200, 'A' };
        // We need letters=true to pass the filter for 'A'
        // We need to be careful with count because surrogates increase/decrease count
        String result = RandomStringUtils.random(2, 0, 0, true, false, surrogates, mockRandom);

        assertNotNull(result);
        // The exact length is non-deterministic due to the logic, but it shouldn't crash
    }


}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen3Test {



















    @Test
    public void testRandom_FilterLogic_NonMatching() {
        // Test when the random char doesn't match letters/numbers/both
        char[] chars = {'1', 'A'};
        // Request letters only, but provide numbers in the array
        // The loop should skip '1' and increment count (effectively decrementing the loop's count)
        // Wait, the code says count++ in the else block, and the loop condition is while(count-- != 0)
        // This is a complex way to handle "try again"
        String result = RandomStringUtils.random(2, 0, 0, true, false, chars, new Random());
        assertEquals(2, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(Character.isLetter(c));
        }
    }
}
